<?php
declare(strict_types=1); require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/csrf.php'; require_once __DIR__.'/connection.php'; require_alumni();$email=$_SESSION['user_email'];$message='';$type='';$survey=null;$questions=[];$r=mysqli_query($connection,'SELECT * FROM surveys WHERE active=1 ORDER BY id DESC LIMIT 1');if($r)$survey=mysqli_fetch_assoc($r);if($survey){$id=(int)$survey['id'];$stmt=mysqli_prepare($connection,'SELECT * FROM survey_questions WHERE survey_id=? ORDER BY sort_order,id');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$r=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($r)){$row['options_array']=preg_split('/[\r\n,]+/',(string)($row['options']??''));$questions[]=$row;}mysqli_stmt_close($stmt);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();mysqli_begin_transaction($connection);try{foreach($questions as $q){$answer=trim($_POST['question_'.$q['id']]??'');if($q['is_required']&&$answer==='')throw new Exception();$stmt=mysqli_prepare($connection,'INSERT INTO survey_responses(survey_id,question_id,email,answer) VALUES(?,?,?,?)');mysqli_stmt_bind_param($stmt,'iiss',$id,$q['id'],$email,$answer);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);}mysqli_commit($connection);$message='Survey submitted successfully.';$type='success';}catch(Throwable $e){mysqli_rollback($connection);$message='Please complete all required questions.';$type='danger';}}}$pageTitle='Survey Forms';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Survey | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><div class="page-head"><h2>Tracer Surveys</h2><p>Your feedback helps improve alumni services.</p></div><?php if($message):?><div class="alert alert-<?=$type?>"><?=htmlspecialchars($message)?></div><?php endif;?><?php if(!$survey):?><div class="panel"><p class="muted">No active survey is available.</p></div><?php else:?><div class="panel"><h2><?=htmlspecialchars($survey['title'])?></h2><p class="muted"><?=htmlspecialchars($survey['description']??'')?></p><form method="post"><?=csrf_field()?><?php foreach($questions as $i=>$q):?><div class="survey-question"><h3><?=($i+1).'. '.htmlspecialchars($q['question'])?></h3><?php if($q['question_type']==='choice'):?><div class="radio-row"><?php foreach($q['options_array'] as $option):?><label class="radio-option"><input type="radio" name="question_<?=$q['id']?>" value="<?=htmlspecialchars(trim($option))?>" <?=$q['is_required']?'required':''?>> <?=htmlspecialchars(trim($option))?></label><?php endforeach;?></div><?php elseif($q['question_type']==='boolean'):?><label class="radio-option"><input type="radio" name="question_<?=$q['id']?>" value="Yes" required> Yes</label><label class="radio-option"><input type="radio" name="question_<?=$q['id']?>" value="No" required> No</label><?php else:?><textarea class="textarea" name="question_<?=$q['id']?>" <?=$q['is_required']?'required':''?>></textarea><?php endif;?></div><?php endforeach;?><button class="btn btn-primary" type="submit">Submit survey</button></form></div><?php endif;?></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
